const ts = require('typescript');
const path = require('path');
const {execFileSync} = require('child_process');

const root = process.cwd();
const configPath = path.join(root, 'tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
if (read.error) {
  console.error('config error', read.error);
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, root);
console.log('fileCount', parsed.fileNames.length);
console.log('optionsErrors', parsed.errors.map(e => ts.flattenDiagnosticMessageText(e.messageText, '\n')));

const rels = [
  'src/screens/medical-records-detail-screen/medical-records-detail-screen.tsx',
  'src/screens/medical-records-detail-screen/medical-records-detail-screen.styles.ts',
];
const absTargets = new Set(rels.map(r => path.resolve(root, r)));

function format(diag) {
  const file = diag.file ? path.relative(root, diag.file.fileName) : '';
  const pos = diag.file && diag.start != null ? diag.file.getLineAndCharacterOfPosition(diag.start) : null;
  const loc = pos ? `${pos.line + 1}:${pos.character + 1}` : '';
  return `${file}:${loc} TS${diag.code} cat=${diag.category} ${ts.flattenDiagnosticMessageText(diag.messageText, ' | ')}`;
}

function collect(program, label) {
  const out = [];
  for (const abs of absTargets) {
    const sf = program.getSourceFile(abs);
    if (!sf) {
      out.push(`${label} MISSING ${abs}`);
      continue;
    }
    const diags = [
      ...program.getSyntacticDiagnostics(sf),
      ...program.getSemanticDiagnostics(sf),
      ...program.getSuggestionDiagnostics(sf),
    ];
    if (diags.length === 0) out.push(`${label} ${path.relative(root, abs)} diagnostics=0`);
    for (const d of diags) out.push(`${label} ${format(d)}`);
  }
  return out;
}

const headProgram = ts.createProgram({rootNames: parsed.fileNames, options: parsed.options});
console.log('--- HEAD ---');
console.log(collect(headProgram, 'HEAD').join('\n'));

const baseRef = '315880496a508bb8f96ae740d61fb0117009a6a7';
const overlays = new Map();
for (const rel of rels) {
  const content = execFileSync('git', ['show', `${baseRef}:${rel}`], {encoding: 'utf8'});
  overlays.set(path.resolve(root, rel), content);
}
const host = ts.createCompilerHost(parsed.options, true);
const origRead = host.readFile.bind(host);
host.readFile = (fileName) => {
  const resolved = path.resolve(fileName);
  if (overlays.has(resolved)) return overlays.get(resolved);
  return origRead(fileName);
};
const baseProgram = ts.createProgram({rootNames: parsed.fileNames, options: parsed.options, host});
console.log('--- BASE ---');
console.log(collect(baseProgram, 'BASE').join('\n'));
EOF

